--
-- Struktur untuk view `active_lockouts`
--
DROP TABLE IF EXISTS `active_lockouts`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `active_lockouts`  AS SELECT `al`.`id` AS `id`, `al`.`username` AS `username`, `al`.`ip_address` AS `ip_address`, `al`.`attempt_count` AS `attempt_count`, `al`.`locked_until` AS `locked_until`, `al`.`is_permanent` AS `is_permanent`, `al`.`created_at` AS `created_at`, timestampdiff(MINUTE,current_timestamp(),`al`.`locked_until`) AS `remaining_minutes`, CASE WHEN `al`.`is_permanent` = 1 THEN 'Permanent' WHEN `al`.`locked_until` > current_timestamp() THEN 'Active' ELSE 'Expired' END AS `status` FROM `account_lockouts` AS `al` WHERE `al`.`locked_until` > current_timestamp() ORDER BY `al`.`created_at` DESC ;

-- --------------------------------------------------------

--
-- Struktur untuk view `login_attempt_stats`
--
DROP TABLE IF EXISTS `login_attempt_stats`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `login_attempt_stats`  AS SELECT cast(`login_attempts`.`created_at` as date) AS `attempt_date`, count(0) AS `total_attempts`, count(case when `login_attempts`.`success` = 1 then 1 end) AS `successful_attempts`, count(case when `login_attempts`.`success` = 0 then 1 end) AS `failed_attempts`, count(distinct `login_attempts`.`username`) AS `unique_users`, count(distinct `login_attempts`.`ip_address`) AS `unique_ips`, round(count(case when `login_attempts`.`success` = 1 then 1 end) / count(0) * 100,2) AS `success_rate` FROM `login_attempts` WHERE `login_attempts`.`created_at` >= current_timestamp() - interval 30 day GROUP BY cast(`login_attempts`.`created_at` as date) ORDER BY cast(`login_attempts`.`created_at` as date) DESC ;

